/* ------------------------------------------------------------------ public API (in-process) */

/** What other modules may call in-process: `ctx.use('finance')` (or `ctx.tryUse` for an optional dependency). */
export interface FinancePublicApi {
  /** Effect of a refund on seller earnings and fees, shown before deciding Used by: returns, support, orders. */
  previewRefundImpact(orderItemIds: string[], refund: common.Money, fundedBy: string): Promise<{ sellerEarningsChange: common.Money, feeReturned: common.Money, afterPayout: boolean, note: string }>;
  /** All seller balances together for the sellers header (SellerStats.balances): total = pending + available + held across sellers, the held part, and how many sellers have a negative available balance Used by: sellers, reports. */
  sellerBalanceTotals(): Promise<{ total: common.Money, held: common.Money, negativeCount: number }>;
  /** What a sent refund changed on the seller ledger: the refund (or refund_after_payout) and fee_refund entries posted for it on these order items. Null until payments.refund.sent is booked (then a preview is all there is) Used by: returns. */
  bookedRefundImpact(paymentRefundId: string, orderItemIds: string[]): Promise<{ sellerEarningsChange: common.Money, feeReturned: common.Money, afterPayout: boolean, note: string } | null>;
  /** Fee and seller earnings for a price under the active fee rules Used by: offers, promotions, sellers, orders. */
  calculateFee(input: FeeCalcInput): Promise<FeeCalculation>;
  /** Balances for dashboards and seller detail Used by: sellers, reports, graphql. */
  getSellerBalances(sellerId: string): Promise<SellerBalances>;
  /** Batched getSellerBalances (the admin seller list): the same balances getSellerBalances gives for each seller (zeros for a seller without an account yet), from a few reads for all of them. Ids that are not uuids are left out (getSellerBalances answers them Not found). Used by: sellers. */
  balancesForSellers(sellerIds: string[]): Promise<Map<string, SellerBalances>>;
  /** Posts a seller ad charge, kept separate from commission Used by: advertising. */
  recordAdCharge(input: { sellerId: string, campaignId: string, campaignRef: string, period: common.DateRange, amount: common.Money, description: string }): Promise<LedgerEntry>;
  /** Posts a fulfillment-service fee (storage, handling, receiving, returns processing, removal; kind = the FeeCharge type) to the seller ledger as service_fee, kept separate from commission and ad charges. Same idempotencyKey returns the first entry. Used by: fulfillment-service. */
  recordServiceFee(input: { sellerId: string, amount: common.Money, kind: string, reference: Reference, description: string, idempotencyKey: string }): Promise<LedgerEntry>;
  /** Credits back all or part of an ad charge or service fee (originalEntryId = the LedgerEntry returned by recordAdCharge or recordServiceFee) as charge_credit; never more than the original minus earlier credits. Same idempotencyKey returns the first entry. Used by: advertising, fulfillment-service. */
  creditSellerCharge(input: { sellerId: string, amount: common.Money, originalEntryId: string, reason: string, idempotencyKey: string }): Promise<LedgerEntry>;
  /** Credits a seller without an original charge (fulfillment-service reimbursements for lost or damaged units, goodwill to a seller) as ledger type seller_credit. Up to creditSecondReviewerThreshold it is posted at once (status posted, ledgerEntry set). Above it the credit waits as pending_approval with an approval request (finance.credits.issue) and is posted or rejected on access.approval.decided, publishing finance.seller_credit.decided. Same idempotencyKey returns the first credit. Used by: fulfillment-service. */
  creditSeller(input: { sellerId: string, amount: common.Money, reason: string, reference: Reference, idempotencyKey: string }): Promise<SellerCredit>;
  /** Current state of a credit asked for with creditSeller (posted, pending_approval, rejected or withdrawn), by id or by the caller's idempotency key; replaces re-calling creditSeller to read it back Used by: fulfillment-service. */
  getSellerCredit(by: { creditId?: string, idempotencyKey?: string }): Promise<SellerCredit | null>;
  /** Withdraws a credit still pending_approval (e.g. the reimbursement it pays was reversed): status withdrawn, its approval request is cancelled through access, nothing is posted. A posted credit is refused with ILLEGAL_TRANSITION (reverse it with an adjustment); withdrawing a withdrawn credit returns it unchanged Used by: fulfillment-service. */
  withdrawSellerCredit(input: { creditId?: string, idempotencyKey?: string, reason: string }): Promise<SellerCredit>;
  /** Another module reports a money difference it found in its own books for the daily check (wallet: a customer balance that differs from its ledger sum). Creates an open reconciliation item on today's day for check store_credit (finance.reconciliation.mismatch_found); the same key returns the existing item, and a later report with expected = actual matches it (finance.reconciliation.item_closed) Used by: wallet. */
  recordExternalDifference(input: { check: 'store_credit', subject: string, description: string, expected: common.Money, actual: common.Money, reference?: Reference, key: string }): Promise<ReconItem>;
  /** Company trading costs for the Official Store margin Used by: purchasing, inventory, shipping, warehouse. */
  recordCompanyCost(input: { kind: 'buying_cost' | 'shipping_expense' | 'return_loss' | 'write_off' | 'supplier_credit', amount: common.Money, reference: Reference, at: string }): Promise<void>;
  /** Whether a seller can be paid (verified destination, no full hold) Used by: sellers. */
  hasPayoutBlock(sellerId: string): Promise<{ blocked: boolean, reasons: string[] }>;
  /** Fee income per seller per market day (commission and fees charged, fee refunds, net, ad income), from fee_charges and ledger_entries. Company revenue only; seller sales are not income. Used by: reports. */
  marketplaceIncomeByDay(range: common.DateRange, sellerId?: string): Promise<DailySellerIncome[]>;
  /** Official Store trading costs per market day and kind (buying cost, Official Store discounts, shipping expense, return losses, write-offs, chargeback losses, supplier credits), from what recordCompanyCost and the order and claim events record in trading_entries. Costs are positive; reversals are negative; supplier credits are positive amounts that lower cost. Used by: reports. */
  companyCostsByDay(range: common.DateRange): Promise<DailyCompanyCost[]>;
  /** One seller's balances, ledger, payouts, statements, holds, amounts owed and adjustments (seller Finance page, admin seller 360) Used by: graphql. */
  getSellerAccount(sellerId: string): Promise<SellerFinanceDetail>;
  /** An itemised statement of this seller Used by: graphql. */
  getStatementForSeller(sellerId: string, ref: string): Promise<Statement | null>;
  /** Any seller's statement as the seller sees it (staff) Used by: graphql. */
  getStatement(ref: string): Promise<Statement | null>;
  /** Payout run with seller rows, holds, approvals, pre-release checks, the last run's failed payouts and destination reviews Used by: graphql. */
  getPayoutRun(ref: string): Promise<PayoutRun & { sellers: common.Page<RunPayoutRow>, failedPayouts: Payout[], destinationReviews: DestinationReview[] } | null>;
  /** Payout runs, newest first Used by: graphql. */
  listPayoutRuns(filter: { status?: string }, page: common.PageInput): Promise<common.Page<PayoutRun>>;
  /** Holds placed for a case, order or chargeback, batched (Case.holds in the dispute view) Used by: graphql, support. */
  holdsForReference(references: { kind: string, id: string }[]): Promise<Hold[]>;
  /** Fee and earnings at a price on the seller's own offer form (calculateFee under the active rules, with the fee basis explained) Used by: offers, graphql. */
  previewOfferEarnings(items: { offerId: string, sellerId: string, categoryId: string | null, price: common.Money }[]): Promise<Record<string, EarningsPreview>>;
  /** The next payout run to be released (draft, pending approval or approved), for the admin dashboard Used by: reports, graphql. */
  getNextPayoutRun(): Promise<PayoutRun | null>;
  /** previewRefundImpact for staff decision panels: resolves the order's items and refundable amounts, then the seller earnings, fee and balance effect Used by: support, returns, graphql. */
  previewRefundImpactForOrder(orderRef: string, items: { orderItemId: string, quantity?: number }[] | null, refund: common.Money | null, fundedBy: string): Promise<RefundImpactPreview>;
  /** Export rows for reports datasets finance.admin.ledger, finance.admin.payout_run, finance.admin.checks, finance.admin.overview (one row per overview figure, filters from, to, basis; G72) and finance.seller.ledger (seller rows scoped to the principal's seller) Used by: reports. */
  exportRows(dataset: string, filters: unknown, principal: identity.Principal, cursor?: string): Promise<{ rows: unknown[], nextCursor?: string }>;
}

/* ------------------------------------------------------------------ tables (row types) */

/** Rows of this module's spec tables, as repositories read them from its collections (`finance.<table>`, ctx.mongo.table(name)). */
export interface FinanceDb {
  /** Running balances per seller (derived from ledger_entries, kept for fast reads) */
  seller_accounts: {
    seller_id: string;
    pending: number;
    available: number;
    held: number;
    currency: string;
    negative_since: Date | null;
    payouts_blocked_reason: string | null;
    fee_override_set_id: string | null;
    /** last market day of the new-seller period, set when sellers.seller.approved is consumed */
    new_seller_until: string | null;
    /** extra days after delivery before earnings become available during the period */
    new_seller_extra_days: number | null;
    updated_at: Date;
  };
  /** Append-only seller ledger. Corrections are new entries, never edits. */
  ledger_entries: {
    id: string;
    seller_id: string;
    at: Date;
    type: string;
    ref_kind: string;
    ref_id: string;
    ref_label: string | null;
    description: string;
    amount: number;
    currency: string;
    bucket: string;
    balance_after: number;
    lot_id: string | null;
    statement_id: string | null;
    recorded_by: string | null;
    source_event_id: string | null;
  };
  /** Net earnings per seller order item, moving pending → available → paid out */
  earnings_lots: {
    id: string;
    seller_id: string;
    order_id: string;
    order_item_id: string;
    state: string;
    gross: number;
    fee: number;
    net: number;
    delivered_at: Date | null;
    available_at: Date | null;
    payout_id: string | null;
  };
  fee_rule_sets: {
    id: string;
    version: string;
    status: string;
    basis: string;
    include_shipping: boolean;
    platform_discounts_reduce_fee: boolean;
    default_rate_bps: number;
    treatment: Json;
    agreement_version: string;
    effective_from: Date | null;
    reason: string | null;
    approval_request_id: string | null;
    created_by: string;
    created_at: Date;
  };
  fee_category_rates: {
    rule_set_id: string;
    category_id: string;
    /** as named when the rule set was proposed */
    category_name: string;
    rate_bps: number;
  };
  /** Fee computed per order item at sale with the rule version used */
  fee_charges: {
    id: string;
    order_item_id: string;
    seller_id: string;
    rule_set_id: string;
    basis_amount: number;
    rate_bps: number;
    fee: number;
    refunded_fee: number;
    status: 'charged' | 'kept_disputed' | 'reversed';
    created_at: Date;
  };
  /** Funding split from returns.refund.approved, applied when payments.refund.sent arrives */
  refund_allocations: {
    refund_request_id: string;
    payment_refund_id: string | null;
    order_id: string;
    owner_type: 'official' | 'seller';
    seller_id: string | null;
    funded_by: string;
    seller_share: number;
    platform_share: number;
    breakdown: Json;
    applied_at: Date | null;
  };
  holds: {
    id: string;
    seller_id: string;
    amount: number;
    released_amount: number;
    currency: string;
    reason_code: string;
    reason: string;
    review_date: string;
    ref_kind: string | null;
    ref_id: string | null;
    status: string;
    placed_by: string;
    placed_at: Date;
    released_at: Date | null;
    release_reason: string | null;
    approval_request_id: string | null;
    /** set when the hold executes a trust recommendation; kept through approval so finance.hold.placed carries it when the approved hold is placed */
    trust_report_id: string | null;
  };
  adjustments: {
    id: string;
    ref: string;
    seller_id: string;
    direction: string;
    amount: number;
    currency: string;
    reason_code: string;
    reason: string;
    ref_kind: string | null;
    ref_id: string | null;
    status: string;
    recorded_by: string;
    approval_request_id: string | null;
    idempotency_key: string | null;
    created_at: Date;
  };
  /** Credits to sellers without an original charge (creditSeller); pending ones wait for finance.credits.issue */
  seller_credits: {
    id: string;
    seller_id: string;
    amount: number;
    currency: string;
    reason: string;
    ref_kind: string;
    ref_id: string;
    ref_label: string | null;
    status: 'posted' | 'pending_approval' | 'rejected' | 'withdrawn';
    idempotency_key: string;
    requested_by: string;
    approval_request_id: string | null;
    ledger_entry_id: string | null;
    created_at: Date;
    decided_at: Date | null;
  };
  amounts_owed: {
    id: string;
    seller_id: string;
    amount: number;
    remaining: number;
    currency: string;
    since: string;
    due_by: string | null;
    status: string;
    origin: Json;
    note: string | null;
    /** a write-off waiting for approval */
    write_off_amount: number | null;
    write_off_reason: string | null;
    /** the pending write-off's access approval request */
    approval_request_id: string | null;
  };
  /** Verification state of the seller's payout account (details stay in sellers) */
  payout_destinations: {
    id: string;
    seller_id: string;
    sellers_account_id: string;
    label: string;
    provider_destination_id: string | null;
    status: string;
    verified_at: Date | null;
    active: boolean;
    pause_until: Date | null;
    deposits_sent_at: Date | null;
    deposit_attempts: number;
  };
  destination_reviews: {
    id: string;
    seller_id: string;
    destination_id: string;
    from_label: string | null;
    to_label: string;
    requested_by: string;
    requested_at: Date;
    status: string;
    checks: Json;
    decided_by: string | null;
    decided_at: Date | null;
    reason: string | null;
  };
  payout_runs: {
    id: string;
    ref: string;
    status: 'draft' | 'pending_approval' | 'approved' | 'releasing' | 'completed' | 'cancelled';
    scheduled_release: Date;
    cutoff_at: Date;
    total: number;
    paying_now: number;
    held: number;
    negative_offset: number;
    currency: string;
    approvals: Json;
    approval_request_id: string | null;
    created_at: Date;
    released_at: Date | null;
    completed_at: Date | null;
  };
  payouts: {
    id: string;
    ref: string;
    seller_id: string;
    run_id: string | null;
    amount: number;
    currency: string;
    status: string;
    destination_id: string;
    requested_on: string;
    released_at: Date | null;
    paid_at: Date | null;
    failed_at: Date | null;
    failure_code: string | null;
    failure_reason: string | null;
    retry_of: string | null;
    provider_payout_id: string | null;
    bank_reference: string | null;
    statement_id: string | null;
    holds_withheld: number;
    negative_offset: number;
    idempotency_key: string | null;
  };
  /** Issued statements are immutable; later corrections appear on the next statement */
  statements: {
    id: string;
    ref: string;
    seller_id: string;
    period_from: string;
    period_to: string;
    status: string;
    issued_at: Date | null;
    payout_id: string | null;
    sections: Json;
    reconciliation: Json;
    rule_version: string;
    pdf_media_id: string | null;
    csv_media_id: string | null;
  };
  /** Company trading facts for the Official Store (never part of seller payouts). Marketplace (platform) facts live in captures, discount_funding, platform_costs and store_credit_liability, never here */
  trading_entries: {
    id: string;
    at: Date;
    kind: 'sale' | 'buying_cost' | 'discount' | 'shipping_expense' | 'return' | 'write_off' | 'chargeback_loss' | 'supplier_credit';
    amount: number;
    currency: string;
    order_id: string | null;
    order_item_id: string | null;
    variant_id: string | null;
    ref_kind: string | null;
    ref_id: string | null;
  };
  /** Official Store sales and margin targets per month, optionally per category */
  trading_targets: {
    id: string;
    period: string;
    category_id: string | null;
    sales_target: number;
    currency: string;
    margin_target_bps: number | null;
    note: string | null;
    set_by: string;
    set_at: Date;
  };
  recon_days: {
    date: string;
    status: string;
    owner_staff_id: string;
    backup_staff_id: string | null;
    due_at: Date;
    checklist: Json;
    completed_by: string | null;
    completed_at: Date | null;
  };
  recon_items: {
    id: string;
    date: string;
    check: string;
    ref_kind: string | null;
    ref_id: string | null;
    subject: string;
    description: string;
    expected: number;
    actual: number;
    /** store credit applied with a captured payment; 0 otherwise */
    credit: number;
    difference: number;
    currency: string;
    detected_at: Date;
    status: string;
    note: string | null;
    owner_staff_id: string | null;
    correction: Json | null;
    approval_request_id: string | null;
  };
  /** Payments captured (payments.payment.captured): the card amount the provider deposits and the store credit applied with it. The provider_deposit check adds up card_amount per market day of captured_at; each capture also has its payments_vs_orders (or unexplained_amount) item in recon_items */
  captures: {
    /** payments capture id */
    id: string;
    /** null for captures recorded before pass 4 */
    intent_id: string | null;
    /** null when no matching order was found, or recorded before pass 4 */
    order_id: string | null;
    group_id: string | null;
    card_amount: number;
    credit_amount: number;
    currency: string;
    provider_ref: string | null;
    captured_at: Date;
    recon_item_id: string | null;
  };
  /** Coupon discount funding per redemption (promotions.coupon.redeemed, promotions.redemption.reversed): the platform part is a marketplace cost, the seller part is funded by the seller. Reversals are negative rows */
  discount_funding: {
    id: string;
    at: Date;
    redemption_id: string;
    funded_by: 'platform' | 'seller';
    kind: 'redeemed' | 'reversed';
    /** signed */
    amount: number;
    currency: string;
    order_id: string | null;
    order_item_id: string | null;
  };
  /** Marketplace (platform) costs and recoveries that are not Official Store trading: labels and refund shares the platform pays on seller orders, carrier claims paid to the platform, platform-funded goodwill store credit, store credit corrections and breakage, written-off seller debts. amount is a cost (positive) or a recovery (negative) */
  platform_costs: {
    id: string;
    at: Date;
    kind: 'label' | 'refund' | 'carrier_claim' | 'goodwill_credit' | 'credit_correction' | 'credit_breakage' | 'write_off';
    /** signed */
    amount: number;
    currency: string;
    order_id: string | null;
    order_item_id: string | null;
    ref_kind: 'label' | 'refund' | 'claim' | 'wallet_entry' | 'amount_owed' | null;
    ref_id: string | null;
  };
  /** Finance's store credit liability, one row per wallet event: granted adds, used, reversed and expired reduce, corrected adds or reduces. The daily store_credit check compares the sum up to a day with wallet.getLiabilityTotal */
  store_credit_liability: {
    id: string;
    at: Date;
    kind: 'granted' | 'used' | 'reversed' | 'expired' | 'corrected';
    /** signed */
    amount: number;
    currency: string;
    /** the wallet ledger entry; null for uses, keyed by order */
    wallet_entry_id: string | null;
    order_id: string | null;
  };
}

