  errorCodes: {
    "DESTINATION_NOT_VERIFIED": {
      "status": 409,
      "meaning": "The seller has no verified payout destination; money stays in the balance."
    },
    "SAME_APPROVER": {
      "status": 409,
      "meaning": "The second approval must come from a different person than the first approver or the requester."
    },
    "RUN_ALREADY_EXISTS": {
      "status": 409,
      "meaning": "A payout run already exists for this cutoff. details.runId."
    },
    "PAYOUT_NOT_RETRYABLE": {
      "status": 409,
      "meaning": "Only failed payouts without an open retry can be retried."
    },
    "STATEMENT_NOT_READY": {
      "status": 409,
      "meaning": "The statement period is still open."
    },
    "CHECKS_INCOMPLETE": {
      "status": 409,
      "meaning": "Destination verification checks are not all passed. details.pending."
    },
    "DEPOSIT_AMOUNTS_INCORRECT": {
      "status": 422,
      "meaning": "The amounts do not match the test deposits. details.attemptsLeft."
    },
    "DEPOSIT_ATTEMPTS_EXCEEDED": {
      "status": 409,
      "meaning": "No tries left; new test deposits must be sent."
    },
    "RECON_DAY_INCOMPLETE": {
      "status": 409,
      "meaning": "Open mismatches remain; explain or correct them first. details.openItems."
    }
  },
